#!/usr/bin/env python3
"""SCC minimal-generator barrier: exact truth-table and tensor regressions."""
from itertools import product
from math import comb
import json

def span(xs):
    b = {}
    for x in xs:
        while x:
            p = x.bit_length()-1
            if p in b: x ^= b[p]
            else:
                b[p] = x
                break
    return b

def rem(b,x):
    for p,y in sorted(b.items(),reverse=True):
        if (x>>p)&1: x ^= y
    return x

def kernel_on(inputs, transform):
    piv, out = {}, []
    for a in inputs:
        x,w = transform(a),a
        while x:
            p=x.bit_length()-1
            if p not in piv:
                piv[p]=(x,w)
                break
            y,z=piv[p];x^=y;w^=z
        if not x: out.append(w)
    return list(span(out).values())

def filt(v,n):
    fs=[span([(1<<(1<<n))-1])]
    for _ in range(n):
        old=list(fs[-1].values())
        fs.append(span(old+[x&y for x in old for y in v]))
    return fs

def check(m):
    n=2*m+2; one=(1<<(1<<n))-1
    coords=[sum(1<<j for j in range(1<<n) if j>>i&1) for i in range(n)]
    g=coords[0]&coords[1];f=g
    for i in range(m):f &= one^(coords[2+2*i]&coords[3+2*i])
    v=[one]+coords;vp=v+[g]
    F,P=filt(v,n),filt(vp,n)
    J=[];JP=[];new=[];restricted_old=[];restricted_new=[]
    for r,(u,w) in enumerate(zip(F,P)):
        # homogeneous degree-r ideals, identifying a*z^r with its truth table.
        j=kernel_on(u.values(),lambda a:rem(u,f&a))
        jp=kernel_on(w.values(),lambda a:rem(w,f&a))
        J.append(j);JP.append(jp)
        # J'_r /(J_r + R'_1 J'_(r-1)) is the generator space of M.
        inherited=j+([x&y for x in vp for y in JP[r-1]] if r else [])
        assert all(rem(span(jp),x)==0 for x in inherited)

#!/usr/bin/env python3
"""Exact finite replay of relative Rees relation births and compositions."""
from itertools import product, combinations
from math import comb
from random import Random
from target_ideal_replay import Space, affine, coords, filt, target, kernel, quotient, draw

def require(ok, msg):
    if not ok:
        raise AssertionError(msg)

def mul(U,V):
    return Space(a&b for a in U for b in V)

def add(*spaces):
    return Space(x for S in spaces for x in S)

def subset(U,V):
    return all(x in V for x in U)

def inter(U,V):
    return kernel(U,V.reduce)

def ext(L,F,r):
    # Unrestricted homogeneous ideal extension, independent of one-gate formula.
    return add(*(mul(L[d+1],F[r-d+1]) for d in range(r+1)))

def data(n,states,fs,f):
    full=(1<<(1<<n))-1
    return [[target(F,s,full) for s in (full^f,f)] for F in fs]

def beta(L,base,V,r):
    den=add(base,mul(V,L[r]))
    require(subset(den,L[r+1]),"generator denominator")
    return len(L[r+1])-len(den)

def one_step(n,F,G,V,W,g,L,M):
    grades=gen=action=nonzero=0
    for r in range(n+1):
        I=add(L[r+1],mul(Space([g]),L[r]))
        require(I.equal(ext(L,G,r)),"one-step inherited ideal")
        require(subset(I,M[r+1]),"quotient defined")
        require(subset(M[r+1],L[r+2]),"z kills quotient")
        K=quotient(M[r+1],F[r+1])
        P=quotient(G[r+1],F[r+1])
        T=quotient(L[r+2],F[r+1])
        require(K.equal(inter(P,T)),"leading symbol intersection")
        qM=Space(F[r+1].reduce(g&a) for a in L[r])
        require(subset(qM,K),"q times old relation")
        require(len(M[r+1])-len(I)==len(K)-len(qM),"Tor dimension")
        b=beta(M,I,W,r)
        require(b>=0,"minimal quotient")
        gen+=b
        if r<n:
            I_next=ext(L,G,r+1)
